export function legalTargetForSlug(slug: string): LegalTargetDocument {
  const document = legalTargetDocuments[slug as LegalTargetSlug];
  if (!document) {
    throw new Error("Unknown legal target slug: " + slug);
  }
  return document;
}

export const legalTargetList = Object.values(legalTargetDocuments);
